package com.bank.statement.repository;

import com.bank.statement.model.Transaction;
import org.springframework.data.jpa.repository.JpaRepository;
import java.time.LocalDate;
import java.util.List;

public interface TransactionRepository extends JpaRepository<Transaction, Long> {

    // SARGABLE query: column is NOT wrapped in a function, so idx_txn_acct_date is used.
    // Generates: WHERE account_id = ? AND txn_date BETWEEN ? AND ?
    List<Transaction> findByAccountIdAndTxnDateBetween(
            String accountId, LocalDate from, LocalDate to);
}
