package com.bank.statement.service;

import com.bank.statement.model.Transaction;
import com.bank.statement.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.time.LocalDate;
import java.util.List;

@Service
public class StatementService {
    private static final Logger log = LoggerFactory.getLogger(StatementService.class);
    private final TransactionRepository repo;

    public StatementService(TransactionRepository repo) { this.repo = repo; }

    public List<Transaction> getStatement(String accountId, LocalDate from, LocalDate to) {
        long start = System.nanoTime();
        // Index-friendly, sargable range query — the DB uses idx_txn_acct_date
        List<Transaction> rows = repo.findByAccountIdAndTxnDateBetween(accountId, from, to);
        long ms = (System.nanoTime() - start) / 1_000_000;
        log.info("Statement for {} from {} to {} returned {} rows in {} ms",
                accountId, from, to, rows.size(), ms);
        return rows;
    }
}
