package com.bank.statement.controller;

import com.bank.statement.model.Transaction;
import com.bank.statement.service.StatementService;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.web.bind.annotation.*;
import java.time.LocalDate;
import java.util.List;

@RestController
@RequestMapping("/api/v1/statements")
public class StatementController {
    private final StatementService service;

    public StatementController(StatementService service) { this.service = service; }

    @GetMapping("/{accountId}")
    public List<Transaction> statement(
            @PathVariable String accountId,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
            @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to) {
        return service.getStatement(accountId, from, to);
    }
}
